/**
 * Create equilateral triangular prism geometry
 * @param {number} sideLength - Side of the equilateral triangle (1.2 units)
 * @param {number} length - Length along the prism axis (1.8 units)
 */
function createTriangularPrism(sideLength, length) {
  const height = (sideLength * Math.sqrt(3)) / 2;
  const halfSide = sideLength / 2;

  const vertices = new Float32Array([
    // Front triangle (z=0)
    -halfSide, 0, 0,
    halfSide, 0, 0,
    0, height, 0,
    // Back triangle (z=length)
    -halfSide, 0, length,
    halfSide, 0, length,
    0, height, length,
  ]);

  const indices = new Uint32Array([
    // Front triangle
    0, 2, 1,
    // Back triangle
    3, 4, 5,
    // Bottom rectangular face
    0, 1, 4, 0, 4, 3,
    // Left slanted face
    0, 3, 5, 0, 5, 2,
    // Right slanted face
    1, 2, 5, 1, 5, 4,
  ]);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geometry.setIndex(new THREE.BufferAttribute(indices, 1));
  geometry.computeVertexNormals();

  return geometry;
}

/**
 * Create caustic gradient texture procedurally
 * Linear gradient: #ff2a38 -> #e8ecf2 -> #9fb0c4
 */
function createCausticGradientTexture() {
  const width = 256;
  const height = 64;
  const data = new Uint8ClampedArray(width * height * 4);

  const c1 = new THREE.Color('#ff2a38');
  const c2 = new THREE.Color('#e8ecf2');
  const c3 = new THREE.Color('#9fb0c4');

  for (let x = 0; x < width; x++) {
    const t = x / width;
    let r, g, b;

    if (t < 0.5) {
      // Interpolate c1 to c2
      const s = t / 0.5;
      r = Math.round((c1.r + (c2.r - c1.r) * s) * 255);
      g = Math.round((c1.g + (c2.g - c1.g) * s) * 255);
      b = Math.round((c1.b + (c2.b - c1.b) * s) * 255);
    } else {
      // Interpolate c2 to c3
      const s = (t - 0.5) / 0.5;
      r = Math.round((c2.r + (c3.r - c2.r) * s) * 255);
      g = Math.round((c2.g + (c3.g - c2.g) * s) * 255);
      b = Math.round((c2.b + (c3.b - c2.b) * s) * 255);
    }

    for (let y = 0; y < height; y++) {
      const idx = (y * width + x) * 4;
      data[idx] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
  texture.needsUpdate = true;

  return texture;
}
